import React, { useState } from "react";
import "../styles/ShiftHandover.css";

function ShiftHandover() {
    const [selectedDate, setSelectedDate] = useState(() => {
        const today = new Date();
        return today.toISOString().split("T")[0]; // Format: YYYY-MM-DD
    });

    const handleDateChange = (e) => {
        setSelectedDate(e.target.value);
    };












    


    // Sample dynamic data
    const shiftData = {
        Morning: [
            {
                name: "Analyst 1",
                remarks: "Checked logs",
                handoverTo: "Analyst A",
                attachment: "LogFile1.pdf"
            },
            {
                name: "Analyst 2",
                remarks: "Updated dashboard",
                handoverTo: "Analyst B",
                attachment: "Dashboard.png"
            }
        ],
        Afternoon: [
            {
                name: "Analyst 3",
                remarks: "Handled alerts",
                handoverTo: "Analyst C",
                attachment: "Alerts.docx"
            },
            {
                name: "Analyst 4",
                remarks: "Reviewed incidents",
                handoverTo: "Analyst D",
                attachment: "Incidents.pdf"
            }
        ],
        Night: [
            {
                name: "Analyst 5",
                remarks: "Ran backups",
                handoverTo: "Analyst E",
                attachment: "Backup.zip"
            },
            {
                name: "Analyst 6",
                remarks: "Verified reports",
                handoverTo: "Analyst F",
                attachment: "Report.xlsx"
            },
            {
                name: "Analyst 7",
                remarks: "System health check",
                handoverTo: "Analyst G",
                attachment: "HealthCheck.txt"
            }
        ]
    };


    return (
        <div className="handover_wrapper">

            <div className="date_area">
                <div className="date_display">
                    <div className="date">
                        Date: {new Date(selectedDate).toLocaleDateString()}
                    </div>
                </div>
                <div className="date_picker">
                    <input
                        type="date"
                        value={selectedDate}
                        onChange={handleDateChange}
                    />
                </div>
                <div className="cluster_label">
                    Cluster 1
                </div>
            </div>


            <div className="timeline_area">
                <div className="ongoing_shift">
                    Ongoing: Morning Shift
                </div>
                <div className="timeline_label">
                    <span className="dot green"></span> Shift Start Time —
                    <span className="dot yellow"></span> Current Time —
                    <span className="dot red"></span> Shift End Time
                </div>
            </div>




            <div className="table_container">
                <table className="table_wrapper">
                    <thead>

                        <tr>
                            <th style={{width:"8%"}}>Shift</th>
                            <th>Name of Analyst</th>
                            <th>Remarks</th>
                            <th>Handover to</th> {/* New column */}
                            <th>Attachment</th>
                            <th>Action</th>
                        </tr>

                    </thead>
                    <tbody>
                        {Object.entries(shiftData).map(([shift, entries]) =>
                            entries.map((entry, index) => (
                                <tr key={`${shift}-${index}`} className={`${shift.toLowerCase()}-row`}>
                                    {index === 0 && (
                                        <th rowSpan={entries.length}>{shift}</th>
                                    )}
                                    <td>{entry.name}</td>
                                    <td>{entry.remarks}</td>
                                    <td>{entry.handoverTo || "—"}</td> {/* New column */}
                                    <td>{entry.attachment}</td>
                                    <td>
                                        <button onClick={() => alert(`${entry.name} has been logged-out of shift!`)}>
                                            Check-out
                                        </button>
                                    </td>
                                </tr>

                            ))
                        )}
                    </tbody>

                </table>
            </div>
        </div>
    );
}

export default ShiftHandover;
